  "name": "pairwise_pref_loss",
  "intuition": "This loss encourages the model to prefer higher-quality outputs by comparing the log probabilities of paired samples, weighted by a cost gap as a measure of preference. By taking the difference in log probabilities scaled by the cost gap, we promote higher probability assignments to better options, aligning with preference learning in RL4CO.",
  "pseudocode": "loss = mean over batch of -logsigmoid((log_prob_w - log_prob_l) * weight)",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "ranking",
    "link_family": "scaled_difference",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    cost_gap = batch.get(\"cost_gap\", ops.zeros_like(log_prob_w))\n    # Compute score differences scaled by cost_gap\n    score_diff = (log_prob_w - log_prob_l) * cost_gap\n    # Compute preference based on sigmoid\n    pref = ops.logsigmoid(score_diff)\n    # Average over batch\n    loss = -ops.mean(pref)\n    return loss"
}

{
  "name": "combined_loss_e1",
  "intuition": "Simplified the combined loss by explicitly adding pseudocode and stabilizing the margin difference with clamping. We clamp the combined logits difference to [-20,20] to prevent numerical instabilities in logsigmoid. The loss mixes margin gap and log probability differences with appropriate scaling while ensuring stable and valid numeric ranges. Weighting is preserved and the pairwise mode expects minimal keys including cost_a and cost_b for cost_gap signal.",
  "pseudocode": "1. Read log_prob_w, log_prob_l, weight, cost_a, cost_b from batch\n2. Compute cost gap = (cost_b - cost_a) detached from gradient\n3. Compute combined logits difference as scaled sum of alpha*(log_prob_w - log_prob_l) and small offset from gap\n4. Clamp logits difference to range [-20, 20] to stabilize logsigmoid\n5. Compute loss = -logsigmoid(combined logits difference)\n6. Multiply by weight if present\n7. Return mean loss over batch pairs",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "clamp_stabilized"
  },
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_a",
      "cost_b"
    ]
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.5))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x1 = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x2 = alpha * 0.675 * (lpw - lpl)\n    x = (x1 + x2) / 2.0\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
}

