{
  "name": "pairwise_pref_loss",
  "intuition": "This loss encourages the model to assign higher probability to preferred sequences by comparing their log_probs, scaled by a cost gap to emphasize differences. Using logsigmoid on the difference of log_probs reduces numerical instability and emphasizes relative preference, making it suitable in RL4CO where relative comparison is crucial for ranking. The pairwise mode facilitates direct comparison between options.",
  "pseudocode": "loss = mean_over_pairs(logsigmoid((log_prob_w - log_prob_l) / (cost_gap + epsilon)))",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "preference_signal",
    "link_family": "log_sigmoid",
    "agg_family": "mean",
    "constraint_family": "monotonic"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    epsilon = 1e-6\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap = batch.get('cost_gap', ops.ones_like(log_prob_w))\n    # Compute pairwise preference score\n    diff = log_prob_w - log_prob_l\n    normalized_diff = div(diff, add(cost_gap, epsilon))\n    pref_score = ops.logsigmoid(normalized_diff)\n    # Weight can optionally scale the loss per pair; default to 1\n    weight = batch.get('weight', ops.ones_like(pref_score))\n    # Compute mean over all pairs\n    loss = ops.mean(ops.mul(pref_score, weight))\n    return loss"
}

