  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    zeros = lpw.new_zeros(lpw.shape)\n    cost_gap = batch.get('cost_gap', batch.get('cost_b', zeros) - batch.get('cost_a', zeros))\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    diff = ops.sub(lpw, lpl)\n    scaled = ops.mul(diff, cost_gap)\n    neg_alpha = ops.neg(lpw.new_full((), alpha))\n    inp = ops.mul(neg_alpha, scaled)\n    loss = ops.softplus(inp)\n    loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
