  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    zeros = lpw.new_zeros(lpw.shape)\n    adv_gap = batch.get('advantage_gap', batch.get('advantage_l', zeros) - batch.get('advantage_w', zeros))\n    rg = ops.rank_gap(lpw, lpl)\n    relu_rg = ops.relu(rg)\n    rg_sq = ops.mul(relu_rg, relu_rg)\n    loss_terms = ops.mul(weight, ops.mul(adv_gap, rg_sq))\n    loss = ops.mean(loss_terms)\n    return loss"
